-- 1. DROP EXISTING TABLES
DROP TABLE IF EXISTS "SystemSetting" CASCADE;
DROP TABLE IF EXISTS "ActivityLog" CASCADE;
DROP TABLE IF EXISTS "DamagePriceConfig" CASCADE;
DROP TABLE IF EXISTS "Inspection" CASCADE;
