DROP TABLE IF EXISTS "FolioCharge" CASCADE;
DROP TABLE IF EXISTS "BookingNote" CASCADE;
DROP TABLE IF EXISTS "Booking" CASCADE;
DROP TABLE IF EXISTS "MaintenanceTicket" CASCADE;
