-- 2. CREATE TABLES
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "email" TEXT UNIQUE NOT NULL, "name" TEXT NOT NULL, "role" TEXT NOT NULL DEFAULT 'GUEST', "phone" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "RoomCategory" ("id" TEXT PRIMARY KEY, "name" TEXT UNIQUE NOT NULL, "description" TEXT NOT NULL, "basePrice" DOUBLE PRECISION NOT NULL, "capacity" INT NOT NULL DEFAULT 2, "sizeSqm" INT, "hasAC" BOOLEAN NOT NULL DEFAULT TRUE, "hasTV" BOOLEAN NOT NULL DEFAULT TRUE, "hasKettle" BOOLEAN NOT NULL DEFAULT TRUE, "hasWater" BOOLEAN NOT NULL DEFAULT TRUE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "RoomImage" ("id" TEXT PRIMARY KEY, "url" TEXT NOT NULL, "roomCategoryId" TEXT NOT NULL REFERENCES "RoomCategory"("id") ON DELETE CASCADE);
CREATE TABLE "Room" ("id" TEXT PRIMARY KEY, "roomNumber" TEXT UNIQUE NOT NULL, "status" TEXT NOT NULL DEFAULT 'AVAILABLE', "roomCategoryId" TEXT NOT NULL REFERENCES "RoomCategory"("id"), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "MaintenanceTicket" ("id" TEXT PRIMARY KEY, "roomId" TEXT NOT NULL REFERENCES "Room"("id") ON DELETE CASCADE, "issue" TEXT NOT NULL, "priority" TEXT NOT NULL DEFAULT 'MEDIUM', "status" TEXT NOT NULL DEFAULT 'REPORTED', "technician" TEXT DEFAULT 'Unassigned', "notes" TEXT, "reportedBy" TEXT NOT NULL DEFAULT 'Front Desk Staff', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Booking" ("id" TEXT PRIMARY KEY, "bookingRef" TEXT UNIQUE NOT NULL, "userId" TEXT NOT NULL REFERENCES "User"("id"), "checkIn" TIMESTAMP(3) NOT NULL, "checkOut" TIMESTAMP(3) NOT NULL, "actualCheckIn" TIMESTAMP(3), "actualCheckOut" TIMESTAMP(3), "adults" INT NOT NULL DEFAULT 2, "children" INT NOT NULL DEFAULT 0, "totalAmount" DOUBLE PRECISION NOT NULL, "discountAmount" DOUBLE PRECISION NOT NULL DEFAULT 0, "taxAmount" DOUBLE PRECISION NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'PENDING', "specialRequests" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "BookingNote" ("id" TEXT PRIMARY KEY, "bookingId" TEXT NOT NULL REFERENCES "Booking"("id") ON DELETE CASCADE, "message" TEXT NOT NULL, "author" TEXT NOT NULL DEFAULT 'Front Desk Staff', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "FolioCharge" ("id" TEXT PRIMARY KEY, "bookingId" TEXT NOT NULL REFERENCES "Booking"("id") ON DELETE CASCADE, "category" TEXT NOT NULL, "description" TEXT NOT NULL, "quantity" INT NOT NULL DEFAULT 1, "unitPrice" DOUBLE PRECISION NOT NULL, "taxAmount" DOUBLE PRECISION NOT NULL DEFAULT 0, "totalAmount" DOUBLE PRECISION NOT NULL, "source" TEXT NOT NULL DEFAULT 'FRONT_DESK', "author" TEXT NOT NULL DEFAULT 'Staff', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "RoomAllocation" ("id" TEXT PRIMARY KEY, "bookingId" TEXT NOT NULL REFERENCES "Booking"("id") ON DELETE CASCADE, "roomId" TEXT NOT NULL REFERENCES "Room"("id"), "checkIn" TIMESTAMP(3) NOT NULL, "checkOut" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Payment" ("id" TEXT PRIMARY KEY, "bookingId" TEXT NOT NULL REFERENCES "Booking"("id") ON DELETE CASCADE, "userId" TEXT NOT NULL REFERENCES "User"("id"), "amount" DOUBLE PRECISION NOT NULL, "currency" TEXT NOT NULL DEFAULT 'INR', "status" TEXT NOT NULL DEFAULT 'PENDING', "paymentMethod" TEXT, "transactionId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ServiceCategory" ("id" TEXT PRIMARY KEY, "name" TEXT UNIQUE NOT NULL);
CREATE TABLE "ServiceItem" ("id" TEXT PRIMARY KEY, "categoryId" TEXT NOT NULL REFERENCES "ServiceCategory"("id"), "name" TEXT NOT NULL, "description" TEXT, "price" DOUBLE PRECISION NOT NULL, "isAvailable" BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE "ServiceOrder" ("id" TEXT PRIMARY KEY, "bookingId" TEXT NOT NULL REFERENCES "Booking"("id") ON DELETE CASCADE, "status" TEXT NOT NULL DEFAULT 'PENDING', "totalAmount" DOUBLE PRECISION NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ServiceOrderItem" ("id" TEXT PRIMARY KEY, "orderId" TEXT NOT NULL REFERENCES "ServiceOrder"("id") ON DELETE CASCADE, "serviceItemId" TEXT NOT NULL REFERENCES "ServiceItem"("id"), "quantity" INT NOT NULL DEFAULT 1, "priceAtTime" DOUBLE PRECISION NOT NULL);
CREATE TABLE "Review" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "rating" INT NOT NULL, "comment" TEXT, "status" TEXT NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SupportTicket" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "subject" TEXT NOT NULL, "message" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'OPEN', "priority" TEXT NOT NULL DEFAULT 'MEDIUM', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ContactInquiry" ("id" TEXT PRIMARY KEY, "fullName" TEXT NOT NULL, "email" TEXT NOT NULL, "phone" TEXT NOT NULL, "inquiryType" TEXT NOT NULL, "message" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'NEW', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Task" ("id" TEXT PRIMARY KEY, "type" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "status" TEXT NOT NULL DEFAULT 'PENDING', "priority" TEXT NOT NULL DEFAULT 'MEDIUM', "assignedStaff" TEXT DEFAULT 'Unassigned', "roomId" TEXT, "bookingId" TEXT, "startTime" TIMESTAMP(3), "completedTime" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Inspection" ("id" TEXT PRIMARY KEY, "roomId" TEXT NOT NULL, "bookingId" TEXT, "inspector" TEXT NOT NULL DEFAULT 'Housekeeping Supervisor', "status" TEXT NOT NULL DEFAULT 'PASSED', "checklistJson" TEXT NOT NULL, "totalDamageCharge" DOUBLE PRECISION NOT NULL DEFAULT 0, "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "DamagePriceConfig" ("id" TEXT PRIMARY KEY, "itemName" TEXT UNIQUE NOT NULL, "price" DOUBLE PRECISION NOT NULL, "category" TEXT NOT NULL DEFAULT 'LINEN_ITEMS', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ActivityLog" ("id" TEXT PRIMARY KEY, "category" TEXT NOT NULL, "action" TEXT NOT NULL, "message" TEXT NOT NULL, "author" TEXT NOT NULL DEFAULT 'System Audit', "roomId" TEXT, "bookingId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SystemSetting" ("id" TEXT PRIMARY KEY, "key" TEXT UNIQUE NOT NULL, "value" TEXT NOT NULL, "category" TEXT NOT NULL DEFAULT 'GENERAL', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);

